// square root by Newton's method: improve a guess until it stops shrinking
define(fp, x29)
define(lr, x30)

n_s = 16                                    // the number read by scanf
alloc = -(16 + 8) & -16
dealloc = -alloc

.data
fmt_in:     .string "%lf"
fmt_root:   .string "square root = %.6f\n"
fmt_neg:    .string "no real square root\n"

.text
        .balign 4
        .global main
main:
        stp     fp, lr, [sp, alloc]!
        mov     fp, sp

        ldr     x0, =fmt_in
        add     x1, fp, n_s
        bl      scanf

        ldr     d1, [fp, n_s]               // d1 = n

        // TODO:
        //   - a negative n prints fmt_neg and returns 1
        //   - 0 is its own root: print it straight away
        //   - otherwise start the guess at n, or at 1.0 when n is below 1,
        //     and repeat  next = (guess + n / guess) / 2  until next is no
        //     longer smaller than guess; guess is then the root
        // fmov d2, xzr puts 0.0 in d2 to compare against, and fmov can
        // load a few small constants directly, 1.0 and 0.5 among them.
        // printf takes the double to print in d0 and fmt_root in x0.

        mov     w0, 0
        ldp     fp, lr, [sp], dealloc
        ret
